/* Heavenly Key shared compact footer app showcase — progressive enhancement, no external dependencies. */
(()=>{'use strict';if(document.getElementById('hk-app-footer-promo'))return;
const css=`
#hk-app-footer-promo{box-sizing:border-box;position:relative;isolation:isolate;width:min(100%,218px);min-height:255px;margin:14px 0 18px;display:flex;align-items:center;justify-content:center;border:1px solid #e4c67d;border-radius:22px;background:linear-gradient(155deg,#fff9e7 0%,#f6f5ed 48%,#eaf5ef 100%);box-shadow:0 12px 28px #251a1830;overflow:hidden;font-family:system-ui,-apple-system,sans-serif;color:#4d2030;text-align:center}
#hk-app-footer-promo *{box-sizing:border-box}#hk-app-footer-promo:before{content:"";position:absolute;inset:-60%;background:conic-gradient(from 0deg,transparent 0deg,#eacb6c66 60deg,transparent 125deg,transparent 360deg);animation:hkPromoHalo 11s linear infinite;z-index:-1}
#hk-app-footer-promo .hk-promo-inner{width:calc(100% - 10px);padding:15px 10px 12px;border-radius:18px;background:linear-gradient(160deg,#fffdf8f5,#f6f1e9ee);min-height:245px;display:flex;flex-direction:column;align-items:center;gap:7px}
#hk-app-footer-promo .hk-promo-kicker{font-size:9px;font-weight:900;letter-spacing:.16em;color:#91672b}#hk-app-footer-promo .hk-promo-phone{width:67px;height:108px;border:4px solid #502138;border-radius:15px;background:linear-gradient(150deg,#1a684c,#70223e);box-shadow:0 6px 13px #34182d55;position:relative;display:grid;place-items:center;animation:hkPromoFloat 4.8s ease-in-out infinite}
#hk-app-footer-promo .hk-promo-phone:before{content:"";position:absolute;top:3px;width:21px;height:4px;background:#1c1820;border-radius:8px}#hk-app-footer-promo .hk-promo-phone span{font-size:26px;color:#f7d56a;text-shadow:0 2px 5px #2c0c21}#hk-app-footer-promo .hk-promo-phone small{position:absolute;bottom:13px;color:white;font-size:8px;font-weight:800;letter-spacing:.04em}
#hk-app-footer-promo strong{font-size:15px;line-height:1.12;color:#592038}#hk-app-footer-promo p{font-size:10px;line-height:1.35;margin:0;color:#56504d}
#hk-app-footer-promo a{display:inline-block;padding:8px 12px;border-radius:30px;background:#6c2140;color:white!important;text-decoration:none!important;font-size:11px;font-weight:800;box-shadow:0 4px 10px #50213844;transition:transform .2s,background .2s}#hk-app-footer-promo a:hover,#hk-app-footer-promo a:focus-visible{background:#205c47;transform:translateY(-2px)}
@keyframes hkPromoFloat{0%,100%{transform:translateY(0) rotate(-3deg)}50%{transform:translateY(-7px) rotate(3deg)}}@keyframes hkPromoHalo{to{transform:rotate(360deg)}}
@media(max-width:600px){#hk-app-footer-promo{width:174px;min-height:228px;margin:12px 0}#hk-app-footer-promo .hk-promo-inner{min-height:218px;padding:10px 8px}#hk-app-footer-promo .hk-promo-phone{width:55px;height:90px}#hk-app-footer-promo strong{font-size:13px}}
@media(prefers-reduced-motion:reduce){#hk-app-footer-promo:before,#hk-app-footer-promo .hk-promo-phone{animation:none}}
`;const style=document.createElement('style');style.id='hk-app-footer-promo-style';style.textContent=css;document.head.appendChild(style);
const el=document.createElement('aside');el.id='hk-app-footer-promo';el.setAttribute('aria-label','Heavenly Key App promotion');el.innerHTML='<div class="hk-promo-inner"><span class="hk-promo-kicker">ONE APP · ONE MISSION</span><div class="hk-promo-phone" aria-hidden="true"><span>✦</span><small>HEAVENLY KEY</small></div><strong>Heavenly Key App</strong><p>Your ministry world in one place.</p><a href="https://heavenlykey.org/pages/app.html" target="_blank" rel="noopener noreferrer" aria-label="Explore Heavenly Key App (opens in a new tab)">Explore the App ↗</a></div>';
const footer=document.querySelector('footer,[role="contentinfo"],.site-footer,.hkem-footer');if(footer){footer.insertBefore(el,footer.firstChild)}else{document.body.appendChild(el)}
})();